  "python": "def pilot_policy(trace):
    if not trace:
        return None
    last_action, last_label = trace[-1]
    params = json.loads(last_action.arguments)
    has_pii = "PII" in last_label.subset
    if last_action.name == "triage/prepare_reply":
        return None
    elif last_action.name == "support/send_reply":
        destination = params.get("destination")
        diagnostics = params.get("diagnostics", False)
        if destination == "forum":
            if has_pii:
                raise PolicyViolation("PII cannot be sent to forum")
            else:
                return None
        elif destination == "private":
            if diagnostics:
                if has_pii:
                    raise PolicyViolation("PII cannot be sent to telemetry via diagnostics")
                else:
                    return None
            else:
                return None
        else:
            return None
    elif last_action.name == "triage/append_help":
        return None
    else:
        raise PolicyViolation("Unknown action")"
